import Link from "next/link";import {CheckCircle2,Clock3,PlusCircle} from "lucide-react";import {Metric} from "@/components/dashboard/shell";import {requireUser} from "@/lib/auth";import {connectMongoose} from "@/lib/db";import {VendorProfileModel} from "@/models/VendorProfile";import {VehicleModel} from "@/models/Vehicle";import {InquiryModel} from "@/models/Inquiry";export default async function Page(){const user=await requireUser("/vendor");await connectMongoose();const profile=await VendorProfileModel.findOne({userId:user.id}).select("_id status displayName").lean();if(!profile)return <div className="card p-8"><h2 className="text-2xl font-bold">Set up your seller profile</h2><p className="mt-2 text-[#68756f]">Complete the short application before adding vehicles.</p><Link className="btn btn-primary mt-6" href="/become-a-vendor">Start seller setup</Link></div>;const[active,pending,inquiries]=await Promise.all([VehicleModel.countDocuments({vendorId:profile._id,status:"ACTIVE"}),VehicleModel.countDocuments({vendorId:profile._id,status:{$in:["DRAFT","PENDING_REVIEW"]}}),InquiryModel.countDocuments({vendorId:String(profile._id),status:{$ne:"CLOSED"}})]);const approved=profile.status==="APPROVED";return <><div className={`mb-7 flex flex-col gap-4 rounded-2xl p-5 sm:flex-row sm:items-center sm:justify-between ${approved?"bg-green-50 text-green-900":"bg-amber-50 text-amber-900"}`}><div className="flex gap-3">{approved?<CheckCircle2/>:<Clock3/>}<div><b>{approved?"Seller account approved":"Application under review"}</b><p className="mt-1 text-sm opacity-75">{approved?"Your listings can be submitted and published.":"You can explore the workspace; listing creation unlocks after approval."}</p></div></div>{approved&&<Link className="btn btn-dark shrink-0" href="/vendor/cars/new"><PlusCircle size={16}/>Add a car</Link>}</div><div className="grid gap-4 sm:grid-cols-3"><Metric label="Active listings" value={active} detail="Visible to buyers"/><Metric label="Draft or review" value={pending} detail="Not live yet"/><Metric label="Open inquiries" value={inquiries} detail="Buyer conversations"/></div><div className="card mt-7 p-6"><h2 className="text-lg font-bold">Welcome, {profile.displayName}</h2><p className="mt-2 text-sm text-[#68756f]">Use Listings to manage inventory and Inquiries to follow up with buyers.</p></div></>}
